-- FFH-P08 account settings and security (design: docs/FFH-P08_PROPOSAL.md §11, binding; R1–R11 approved).
-- Generated by scripts/p08/build-migration.py from scripts/p08/migration-head.sql + migration-tail.sql plus three
-- RPC bodies copied verbatim from earlier migrations (only their sign-in guard changes). Do not edit by hand.
--
-- What it adds:
--   * private.session_ok(): the one assurance predicate. The JWT's session_id must name a LIVE auth.sessions row
--     of auth.uid(); for a person with an FFH-approved authenticator, the JWT and that row must both be aal2 and
--     the row's factor_id must be an approved factor. No security decision compares JWT and database clocks.
--   * Every authorization path requires it: the four household helpers (so every financial/household policy),
--     the profiles and households-insert policies, and every RPC executable by authenticated.
--   * One lock order for membership changes: household row, then invitation rows, then membership rows.
--   * FFH factor registry, single-use recent re-authentication proofs and a security event log (private schema,
--     no grants to anon/authenticated).

begin;

-- ---------------------------------------------------------------------------------------------------------------
-- Private state
-- ---------------------------------------------------------------------------------------------------------------
create table private.mfa_approved_factors (
  factor_id uuid primary key,
  user_id uuid not null references auth.users(id) on delete cascade,
  approved_at timestamptz not null default now()
);
create index mfa_approved_factors_user_idx on private.mfa_approved_factors (user_id);

create table private.reauth_uses (
  session_id uuid not null,
  purpose text not null check (purpose in ('password_change', 'mfa_approve', 'mfa_revoke', 'delete_account')),
  user_id uuid not null references auth.users(id) on delete cascade,
  used_at timestamptz not null default now(),
  primary key (session_id, purpose)
);

-- No foreign key: an account-deletion or Owner-reset row must outlive the account it describes. No secrets, no email.
create table private.security_events (
  id bigint generated always as identity primary key,
  user_id uuid not null,
  event text not null check (event in ('password_changed', 'mfa_approved', 'mfa_revoked', 'account_deleted', 'owner_mfa_reset')),
  detail text,
  created_at timestamptz not null default now()
);

revoke all on private.mfa_approved_factors, private.reauth_uses, private.security_events from public, anon, authenticated;

-- ---------------------------------------------------------------------------------------------------------------
-- The assurance predicate
-- ---------------------------------------------------------------------------------------------------------------
create or replace function private.has_approved_factor(p_user uuid)
returns boolean
language sql
stable
security definer
set search_path = ''
as $$
  select exists (select 1 from private.mfa_approved_factors f where f.user_id = p_user);
$$;

create or replace function private.session_ok()
returns boolean
language plpgsql
stable
security definer
set search_path = ''
as $$
declare
  v_user uuid := auth.uid();
  v_claims jsonb;
  v_session uuid;
  v_aal text;
  v_factor uuid;
  v_not_after timestamptz;
begin
  if v_user is null then
    return false;
  end if;
  begin
    v_claims := auth.jwt();
    v_session := (v_claims ->> 'session_id')::uuid;
  exception when others then
    return false;
  end;
  if v_session is null or jsonb_typeof(v_claims) <> 'object' then
    return false;
  end if;
  select s.aal::text, s.factor_id, s.not_after into v_aal, v_factor, v_not_after
  from auth.sessions s
  where s.id = v_session and s.user_id = v_user;
  if not found or (v_not_after is not null and v_not_after <= now()) then
    return false;
  end if;
  if not private.has_approved_factor(v_user) then
    return true;
  end if;
  return coalesce(v_claims ->> 'aal', '') = 'aal2'
    and v_aal = 'aal2'
    and v_factor is not null
    and exists (select 1 from private.mfa_approved_factors f where f.user_id = v_user and f.factor_id = v_factor);
end;
$$;

revoke all on function private.has_approved_factor(uuid), private.session_ok() from public, anon, authenticated;
-- RLS policies evaluate as the caller, so the predicate itself must be executable by authenticated.
grant execute on function private.session_ok() to authenticated;

-- ---------------------------------------------------------------------------------------------------------------
-- Household helpers: every household and financial policy goes through one of these four.
-- ---------------------------------------------------------------------------------------------------------------
create or replace function private.is_household_member(target_household_id uuid)
returns boolean
language sql
stable
security definer
set search_path = ''
as $$
  select private.session_ok() and exists (
    select 1
    from public.household_members hm
    where hm.household_id = target_household_id
      and hm.user_id = (select auth.uid())
  );
$$;

create or replace function private.can_read_household(target_household_id uuid)
returns boolean
language sql
stable
security definer
set search_path = ''
as $$
  select private.session_ok() and exists (
    select 1
    from public.household_members hm
    where hm.household_id = target_household_id
      and hm.user_id = (select auth.uid())
  );
$$;

create or replace function private.can_write_household_financials(target_household_id uuid)
returns boolean
language sql
stable
security definer
set search_path = ''
as $$
  select private.session_ok() and exists (
    select 1
    from public.household_members hm
    where hm.household_id = target_household_id
      and hm.user_id = (select auth.uid())
      and hm.role in ('owner', 'member')
  );
$$;

create or replace function private.is_household_owner(target_household_id uuid)
returns boolean
language sql
stable
security definer
set search_path = ''
as $$
  select private.session_ok() and exists (
    select 1
    from public.household_members hm
    where hm.household_id = target_household_id
      and hm.user_id = (select auth.uid())
      and hm.role = 'owner'
  );
$$;

-- ---------------------------------------------------------------------------------------------------------------
-- The four policies that did not go through a helper.
-- ---------------------------------------------------------------------------------------------------------------
drop policy "profiles_select_self" on public.profiles;
drop policy "profiles_insert_self" on public.profiles;
drop policy "profiles_update_self" on public.profiles;
drop policy "households_insert_creator" on public.households;

create policy "profiles_select_self" on public.profiles for select to authenticated
  using (id = (select auth.uid()) and (select private.session_ok()));
create policy "profiles_insert_self" on public.profiles for insert to authenticated
  with check (id = (select auth.uid()) and (select private.session_ok()));
create policy "profiles_update_self" on public.profiles for update to authenticated
  using (id = (select auth.uid()) and (select private.session_ok()))
  with check (id = (select auth.uid()) and (select private.session_ok()));
create policy "households_insert_creator" on public.households for insert to authenticated
  with check (created_by = (select auth.uid()) and (select private.session_ok()));

-- ---------------------------------------------------------------------------------------------------------------
-- Membership RPCs: household row first, then invitation, then membership (proposal §11.4).
-- ---------------------------------------------------------------------------------------------------------------
create or replace function public.accept_household_invitation(p_token text)
returns uuid
language plpgsql
security definer
set search_path = ''
as $$
declare
  v_user uuid := auth.uid();
  v_hash text;
  v_household uuid;
  v_invite public.household_invitations%rowtype;
begin
  if v_user is null or not private.session_ok() then
    raise exception 'permission denied: not signed in' using errcode = '42501';
  end if;
  if p_token is null or p_token !~ '^[A-Za-z0-9_-]{43}$' then
    raise exception 'permission denied: this invitation is not valid' using errcode = '42501';
  end if;
  v_hash := encode(sha256(convert_to(p_token, 'UTF8')), 'hex');

  -- 1. Non-locking lookup, only to learn which household to lock.
  select i.household_id into v_household from public.household_invitations i where i.token_hash = v_hash;
  if not found then
    raise exception 'permission denied: this invitation is not valid' using errcode = '42501';
  end if;
  -- 2. Household row first (account deletion takes the same lock first).
  perform 1 from public.households h where h.id = v_household for update;
  if not found then
    raise exception 'permission denied: this invitation is not valid' using errcode = '42501';
  end if;
  -- 3. Then the invitation, re-validated under the household lock.
  select * into v_invite from public.household_invitations
  where token_hash = v_hash
  for update;
  if not found or v_invite.household_id <> v_household
     or v_invite.accepted_at is not null or v_invite.expires_at <= now() then
    raise exception 'permission denied: this invitation is not valid' using errcode = '42501';
  end if;
  if exists (select 1 from public.household_members where user_id = v_user) then
    raise exception 'permission denied: you already belong to a household' using errcode = '42501';
  end if;

  -- The UNIQUE(user_id) constraint, not this prior SELECT, is the final
  -- concurrency and household-creation invariant.
  begin
    insert into public.household_members (household_id, user_id, role)
    values (v_invite.household_id, v_user, v_invite.role);
  exception when unique_violation then
    raise exception 'permission denied: you already belong to a household' using errcode = '42501';
  end;
  update public.household_invitations
  set accepted_at = now(), accepted_by = v_user
  where id = v_invite.id;

  return v_invite.household_id;
end;
$$;

-- Owner only: change another person's role between member and viewer.
create or replace function public.set_household_member_role(p_household_id uuid, p_user_id uuid, p_role public.household_role)
returns void
language plpgsql
security definer
set search_path = ''
as $$
begin
  if auth.uid() is null or not private.session_ok() or not private.is_household_owner(p_household_id) then
    raise exception 'permission denied: only the household owner can change roles' using errcode = '42501';
  end if;
  if p_role is null or p_role not in ('member', 'viewer') then
    raise exception 'setup: role must be member or viewer' using errcode = '22023';
  end if;
  perform 1 from public.households h where h.id = p_household_id for update;
  update public.household_members
  set role = p_role
  where household_id = p_household_id and user_id = p_user_id and role <> 'owner';
  if not found then
    raise exception 'permission denied: that person cannot be changed' using errcode = '42501';
  end if;
end;
$$;

-- Owner only: remove another person from the household. The owner is never removed.
create or replace function public.remove_household_member(p_household_id uuid, p_user_id uuid)
returns void
language plpgsql
security definer
set search_path = ''
as $$
begin
  if auth.uid() is null or not private.session_ok() or not private.is_household_owner(p_household_id) then
    raise exception 'permission denied: only the household owner can remove people' using errcode = '42501';
  end if;
  perform 1 from public.households h where h.id = p_household_id for update;
  delete from public.household_members
  where household_id = p_household_id and user_id = p_user_id and role <> 'owner';
  if not found then
    raise exception 'permission denied: that person cannot be removed' using errcode = '42501';
  end if;
end;
$$;

-- complete_household_setup: copied from 20261113230000_ffh_p05_atomic_household_setup.sql; only the sign-in guard changed.
create or replace function public.complete_household_setup(
  p_take_home numeric,
  p_fixed_bills numeric,
  p_other_spending numeric,
  p_debt_balance numeric,
  p_debt_minimum numeric,
  p_debt_rate numeric,
  p_savings numeric,
  p_savings_purpose text,
  p_simple_view boolean
)
returns text
language plpgsql
security invoker
set search_path = ''
as $$
declare
  v_user uuid := auth.uid();
  v_household uuid;
  v_max constant numeric := 999999999999.99;
begin
  if v_user is null or not private.session_ok() then
    raise exception 'permission denied: not signed in' using errcode = '42501';
  end if;

  -- Validate every answer before reading or writing anything.
  if p_take_home is null or p_fixed_bills is null or p_other_spending is null or p_simple_view is null then
    raise exception 'setup: a required answer is missing' using errcode = '22023';
  end if;
  if p_take_home < 0 or p_take_home > v_max or p_fixed_bills < 0 or p_fixed_bills > v_max
     or p_other_spending < 0 or p_other_spending > v_max then
    raise exception 'setup: an amount is out of range' using errcode = '22023';
  end if;
  if (p_debt_balance is not null and (p_debt_balance < 0 or p_debt_balance > v_max))
     or (p_debt_minimum is not null and (p_debt_minimum < 0 or p_debt_minimum > v_max))
     or (p_debt_rate is not null and (p_debt_rate < 0 or p_debt_rate > 100)) then
    raise exception 'setup: a debt answer is out of range' using errcode = '22023';
  end if;
  if coalesce(p_debt_balance, 0) > 0 and p_debt_minimum is null then
    raise exception 'setup: a debt needs its monthly minimum' using errcode = '22023';
  end if;
  if coalesce(p_debt_balance, 0) = 0 and (p_debt_minimum is not null or p_debt_rate is not null) then
    raise exception 'setup: debt details need a debt balance' using errcode = '22023';
  end if;
  if p_savings is not null and (p_savings < 0 or p_savings > v_max) then
    raise exception 'setup: savings is out of range' using errcode = '22023';
  end if;
  if coalesce(p_savings, 0) > 0
     and (p_savings_purpose is null or p_savings_purpose not in ('protected_reserve', 'unallocated', 'operating_cash')) then
    raise exception 'setup: savings needs a chosen purpose' using errcode = '22023';
  end if;
  if coalesce(p_savings, 0) = 0 and p_savings_purpose is not null then
    raise exception 'setup: a savings purpose needs a savings amount' using errcode = '22023';
  end if;

  -- The caller's own oldest household (visible only through the caller's membership).
  select h.id into v_household
  from public.households h
  join public.household_members m on m.household_id = h.id and m.user_id = v_user
  order by h.created_at, h.id
  limit 1;
  if v_household is null then
    raise exception 'permission denied: no household for this user' using errcode = '42501';
  end if;

  -- One setup at a time per household; released automatically at commit or rollback.
  perform pg_advisory_xact_lock(hashtextextended('ffh-setup:' || v_household::text, 0));

  -- Never runs on a household that already has records: nothing is written.
  if exists (select 1 from public.income_sources where household_id = v_household)
     or exists (select 1 from public.expenses where household_id = v_household)
     or exists (select 1 from public.debts where household_id = v_household)
     or exists (select 1 from public.accounts where household_id = v_household) then
    return 'already_set_up';
  end if;

  if p_take_home > 0 then
    insert into public.income_sources (household_id, name, monthly_amount)
    values (v_household, 'Take-home pay (from setup)', p_take_home);
  end if;
  if p_fixed_bills > 0 then
    insert into public.expenses (household_id, name, category, monthly_amount, is_essential)
    values (v_household, 'Fixed bills and must-haves (from setup)', 'other', p_fixed_bills, true);
  end if;
  if p_other_spending > 0 then
    insert into public.expenses (household_id, name, category, monthly_amount, is_essential)
    values (v_household, 'Other spending (from setup)', 'personal', p_other_spending, false);
  end if;
  if coalesce(p_debt_balance, 0) > 0 then
    insert into public.debts (household_id, name, debt_type, current_balance, minimum_payment, interest_rate)
    values (v_household, 'Debts (from setup)', 'other', p_debt_balance, p_debt_minimum, p_debt_rate);
  end if;
  if coalesce(p_savings, 0) > 0 then
    insert into public.accounts (household_id, name, account_type, balance, cash_purpose)
    values (v_household, 'Savings (from setup)', 'savings', p_savings, p_savings_purpose);
  end if;
  if p_simple_view then
    insert into public.profiles (id, simple_mode) values (v_user, true)
    on conflict (id) do update set simple_mode = true, updated_at = now();
  end if;

  return 'saved';
end;
$$;

-- create_monthly_check_in: copied from 20261114120000_ffh_p07_check_in_write_integrity.sql; only the sign-in guard changed.
create or replace function public.create_monthly_check_in(
  p_month date,
  p_followed_plan boolean,
  p_balances jsonb
)
returns uuid
language plpgsql
security definer
set search_path = ''
as $$
declare
  v_user uuid := auth.uid();
  v_household uuid;
  v_check_in uuid;
  v_line jsonb;
  v_item record;
  v_index integer := 0;
  v_entries integer;
  v_matched integer := 0;
begin
  if v_user is null or not private.session_ok() then
    raise exception 'permission denied: not signed in' using errcode = '42501';
  end if;
  if p_month is null or p_followed_plan is null or p_balances is null
     or jsonb_typeof(p_balances) <> 'array' or jsonb_array_length(p_balances) > 300 then
    raise exception 'check-in: a required answer is missing or malformed' using errcode = '22023';
  end if;
  if extract(day from p_month) <> 1 then
    raise exception 'check-in: month must be the first day of a month' using errcode = '22023';
  end if;
  for v_line in select value from jsonb_array_elements(p_balances) loop
    if jsonb_typeof(v_line) <> 'object'
       or jsonb_typeof(v_line -> 'item_type') is distinct from 'string'
       or (v_line ->> 'item_type') not in ('account', 'retirement_account', 'debt')
       or jsonb_typeof(v_line -> 'item_id') is distinct from 'string'
       or (v_line ->> 'item_id') !~ '^[0-9a-fA-F]{8}-[0-9a-fA-F]{4}-[0-9a-fA-F]{4}-[0-9a-fA-F]{4}-[0-9a-fA-F]{12}$' then
      raise exception 'check-in: a balance line is malformed' using errcode = '22023';
    end if;
    perform private.check_in_amount(v_line -> 'amount');
  end loop;
  -- No item may be listed twice.
  if (select count(*) from jsonb_array_elements(p_balances))
     <> (select count(distinct (e ->> 'item_type', lower(e ->> 'item_id'))) from jsonb_array_elements(p_balances) e) then
    raise exception 'check-in: a balance is listed more than once' using errcode = '22023';
  end if;

  -- One household per account (household_members_one_household_per_user).
  select m.household_id into v_household
  from public.household_members m
  where m.user_id = v_user;
  if v_household is null then
    raise exception 'permission denied: no household for this user' using errcode = '42501';
  end if;
  if not private.can_write_household_financials(v_household) then
    raise exception 'permission denied: viewers cannot save check-ins' using errcode = '42501';
  end if;

  insert into public.monthly_check_ins (household_id, check_in_month, followed_plan)
  values (v_household, p_month, p_followed_plan)
  returning id into v_check_in;

  -- The lines are the household's profile items, in profile order; every one needs an entry.
  for v_item in
    select 'account'::text as item_type, a.id, a.name, 1 as kind_order, a.created_at
      from public.accounts a where a.household_id = v_household and a.include_in_net_worth
    union all
    select 'retirement_account', r.id, r.name, 2, r.created_at
      from public.retirement_accounts r where r.household_id = v_household
    union all
    select 'debt', d.id, d.name, 3, d.created_at
      from public.debts d where d.household_id = v_household
    order by kind_order, created_at, id
  loop
    select e into v_line from jsonb_array_elements(p_balances) e
    where e ->> 'item_type' = v_item.item_type and lower(e ->> 'item_id') = v_item.id::text;
    if v_line is null then
      raise exception 'check-in: a balance is missing for a Financial profile item' using errcode = '22023';
    end if;
    insert into public.monthly_check_in_balances (household_id, check_in_id, item_type, name, amount, sort_order)
    values (v_household, v_check_in, v_item.item_type, left(v_item.name, 100),
            private.check_in_amount(v_line -> 'amount'), v_index);
    v_index := v_index + 1;
    v_matched := v_matched + 1;
  end loop;

  v_entries := jsonb_array_length(p_balances);
  if v_entries <> v_matched then
    raise exception 'check-in: a balance does not match a Financial profile item' using errcode = '22023';
  end if;
  return v_check_in;
end;
$$;

-- update_monthly_check_in: copied from 20261114130000_ffh_p07_check_in_edit_lock.sql; only the sign-in guard changed.
create or replace function public.update_monthly_check_in(
  p_check_in_id uuid,
  p_followed_plan boolean,
  p_amounts jsonb
)
returns void
language plpgsql
security definer
set search_path = ''
as $$
declare
  v_user uuid := auth.uid();
  v_household uuid;
  v_line jsonb;
  v_rows integer;
  v_lines integer;
begin
  if v_user is null or not private.session_ok() then
    raise exception 'permission denied: not signed in' using errcode = '42501';
  end if;
  if p_check_in_id is null or p_followed_plan is null or p_amounts is null
     or jsonb_typeof(p_amounts) <> 'array' or jsonb_array_length(p_amounts) > 300 then
    raise exception 'check-in: a required answer is missing or malformed' using errcode = '22023';
  end if;
  for v_line in select value from jsonb_array_elements(p_amounts) loop
    if jsonb_typeof(v_line) <> 'object' or jsonb_typeof(v_line -> 'id') is distinct from 'string'
       or (v_line ->> 'id') !~ '^[0-9a-fA-F]{8}-[0-9a-fA-F]{4}-[0-9a-fA-F]{4}-[0-9a-fA-F]{4}-[0-9a-fA-F]{12}$' then
      raise exception 'check-in: a balance line is malformed' using errcode = '22023';
    end if;
    perform private.check_in_amount(v_line -> 'amount');
  end loop;
  if (select count(*) from jsonb_array_elements(p_amounts))
     <> (select count(distinct lower(e ->> 'id')) from jsonb_array_elements(p_amounts) e) then
    raise exception 'check-in: a balance is listed more than once' using errcode = '22023';
  end if;

  select m.household_id into v_household
  from public.household_members m
  where m.user_id = v_user;
  -- The same refusal for "not yours", "not found" and "viewer", so nothing is disclosed.
  if v_household is null or not private.can_write_household_financials(v_household)
     or not exists (select 1 from public.monthly_check_ins c
                    where c.id = p_check_in_id and c.household_id = v_household) then
    raise exception 'permission denied: check-in not found or not editable' using errcode = '42501';
  end if;

  -- Review N01: lock the check-in row first, so simultaneous edits of the same check-in run one
  -- after the other instead of locking its lines in different orders and deadlocking.
  perform 1 from public.monthly_check_ins c
  where c.id = p_check_in_id and c.household_id = v_household
  for update;

  select count(*) into v_lines from public.monthly_check_in_balances
  where check_in_id = p_check_in_id and household_id = v_household;
  if v_lines <> jsonb_array_length(p_amounts) then
    raise exception 'check-in: every balance line needs exactly one amount' using errcode = '22023';
  end if;

  for v_line in select value from jsonb_array_elements(p_amounts) loop
    update public.monthly_check_in_balances
    set amount = private.check_in_amount(v_line -> 'amount')
    where id = (v_line ->> 'id')::uuid and check_in_id = p_check_in_id and household_id = v_household;
    get diagnostics v_rows = row_count;
    if v_rows <> 1 then
      raise exception 'check-in: a balance line does not belong to this check-in' using errcode = '22023';
    end if;
  end loop;

  -- Always stamps updated_by/updated_at (trigger); the planned cash-flow snapshot stays frozen.
  update public.monthly_check_ins set followed_plan = p_followed_plan
  where id = p_check_in_id and household_id = v_household;
end;
$$;

-- ---------------------------------------------------------------------------------------------------------------
-- Recent re-authentication (proposal §10.1.4 / §11.3). A provider-signed JWT whose amr shows a password sign-in
-- (and, with an approved authenticator, a TOTP verification) in the last 5 minutes, +30 s for clock skew.
-- Refreshing a session keeps the original amr timestamps (spike), so a stolen older or refreshed token is never a
-- proof. Single use per session and purpose; consumed in the caller's transaction.
-- ---------------------------------------------------------------------------------------------------------------
create or replace function private.amr_age(p_claims jsonb, p_method text)
returns bigint
language sql
stable
set search_path = ''
as $$
  select extract(epoch from now())::bigint - max((e ->> 'timestamp')::bigint)
  from jsonb_array_elements(case when jsonb_typeof(p_claims -> 'amr') = 'array' then p_claims -> 'amr' else '[]'::jsonb end) e
  where jsonb_typeof(e) = 'object' and e ->> 'method' = p_method
    and jsonb_typeof(e -> 'timestamp') = 'number' and (e ->> 'timestamp') ~ '^[0-9]{1,12}$';
$$;

create or replace function private.recent_reauth(p_purpose text)
returns void
language plpgsql
volatile
security definer
set search_path = ''
as $$
declare
  v_user uuid := auth.uid();
  v_claims jsonb := auth.jwt();
  v_age bigint;
begin
  if v_user is null or not private.session_ok() then
    raise exception 'permission denied: please sign in again' using errcode = '42501';
  end if;
  v_age := private.amr_age(v_claims, 'password');
  if v_age is null or v_age > 330 or v_age < -30 then
    raise exception 'permission denied: please confirm your password again' using errcode = '42501';
  end if;
  if private.has_approved_factor(v_user) then
    v_age := private.amr_age(v_claims, 'totp');
    if v_age is null or v_age > 330 or v_age < -30 then
      raise exception 'permission denied: please confirm your password again' using errcode = '42501';
    end if;
  end if;
  begin
    insert into private.reauth_uses (session_id, purpose, user_id)
    values ((v_claims ->> 'session_id')::uuid, p_purpose, v_user);
  exception when unique_violation then
    raise exception 'permission denied: please confirm your password again' using errcode = '42501';
  end;
end;
$$;

revoke all on function private.amr_age(jsonb, text), private.recent_reauth(text) from public, anon, authenticated;

-- ---------------------------------------------------------------------------------------------------------------
-- Status for the app's sign-in gate. The ONE allowlisted function that does not require session_ok(): it needs a
-- live session (so a revoked token learns nothing) and returns only the caller's own status and approved factor ids.
-- ---------------------------------------------------------------------------------------------------------------
create or replace function public.my_security_status()
returns jsonb
language plpgsql
stable
security definer
set search_path = ''
as $$
declare
  v_user uuid := auth.uid();
  v_session uuid;
begin
  begin
    v_session := (auth.jwt() ->> 'session_id')::uuid;
  exception when others then
    v_session := null;
  end;
  if v_user is null or v_session is null
     or not exists (select 1 from auth.sessions s where s.id = v_session and s.user_id = v_user
                    and (s.not_after is null or s.not_after > now())) then
    raise exception 'permission denied: not signed in' using errcode = '42501';
  end if;
  return jsonb_build_object(
    'two_factor_on', private.has_approved_factor(v_user),
    'session_ok', private.session_ok(),
    'approved_factor_ids', coalesce((select jsonb_agg(a.factor_id order by a.approved_at)
                                     from private.mfa_approved_factors a where a.user_id = v_user), '[]'::jsonb),
    'unapproved_factor', exists (
      select 1 from auth.mfa_factors f
      where f.user_id = v_user and f.status::text = 'verified'
        and not exists (select 1 from private.mfa_approved_factors a where a.factor_id = f.id)));
end;
$$;

-- ---------------------------------------------------------------------------------------------------------------
-- Session revocation by deleting session rows (proposal §11.1). Refresh tokens cascade with their session.
-- ---------------------------------------------------------------------------------------------------------------
create or replace function private.end_sessions(p_user uuid, p_keep uuid)
returns void
language sql
volatile
security definer
set search_path = ''
as $$
  delete from auth.sessions s where s.user_id = p_user and (p_keep is null or s.id <> p_keep);
$$;

revoke all on function private.end_sessions(uuid, uuid) from public, anon, authenticated;

-- Part A: after the provider changed the password (it requires the current password; R9), end EVERY session of
-- the person, including the one that made the change. They sign in again with the new password.
create or replace function public.finish_password_change()
returns void
language plpgsql
volatile
security definer
set search_path = ''
as $$
declare
  v_user uuid := auth.uid();
begin
  perform private.recent_reauth('password_change');
  insert into private.security_events (user_id, event) values (v_user, 'password_changed');
  perform private.end_sessions(v_user, null);
end;
$$;

-- ---------------------------------------------------------------------------------------------------------------
-- Part B: FFH factor registry.
-- ---------------------------------------------------------------------------------------------------------------
-- First authenticator: the acting session must have just been verified WITH this factor (row factor_id).
-- Another authenticator: session_ok() already proves aal2 through an approved factor; the new factor must be a
-- verified TOTP factor of the caller. Either way a fresh password sign-in is required. Ends every session.
create or replace function public.approve_my_mfa_factor(p_factor_id uuid)
returns void
language plpgsql
volatile
security definer
set search_path = ''
as $$
declare
  v_user uuid := auth.uid();
  v_claims jsonb := auth.jwt();
  v_age bigint;
  v_aal text;
  v_session_factor uuid;
begin
  perform private.recent_reauth('mfa_approve');
  if p_factor_id is null or not exists (
       select 1 from auth.mfa_factors f
       where f.id = p_factor_id and f.user_id = v_user and f.factor_type::text = 'totp' and f.status::text = 'verified') then
    raise exception 'permission denied: that authenticator cannot be approved' using errcode = '42501';
  end if;
  if exists (select 1 from private.mfa_approved_factors a where a.factor_id = p_factor_id) then
    raise exception 'permission denied: that authenticator is already on' using errcode = '42501';
  end if;
  if not private.has_approved_factor(v_user) then
    select s.aal::text, s.factor_id into v_aal, v_session_factor
    from auth.sessions s where s.id = (v_claims ->> 'session_id')::uuid and s.user_id = v_user;
    v_age := private.amr_age(v_claims, 'totp');
    if coalesce(v_claims ->> 'aal', '') <> 'aal2' or v_aal is distinct from 'aal2'
       or v_session_factor is distinct from p_factor_id or v_age is null or v_age > 330 or v_age < -30 then
      raise exception 'permission denied: that authenticator cannot be approved' using errcode = '42501';
    end if;
  end if;
  insert into private.mfa_approved_factors (factor_id, user_id) values (p_factor_id, v_user);
  insert into private.security_events (user_id, event) values (v_user, 'mfa_approved');
  perform private.end_sessions(v_user, null);
end;
$$;

-- Turning two-factor sign-in off: fresh password + code (recent_reauth). Removes EVERY approval at once (a proof is
-- single-use per operation). Ends every OTHER session; the acting session then unenrolls the factors with the
-- provider and signs out.
create or replace function public.turn_off_my_two_factor()
returns void
language plpgsql
volatile
security definer
set search_path = ''
as $$
declare
  v_user uuid := auth.uid();
begin
  perform private.recent_reauth('mfa_revoke');
  delete from private.mfa_approved_factors a where a.user_id = v_user;
  if not found then
    raise exception 'permission denied: two-factor sign-in is not on' using errcode = '42501';
  end if;
  insert into private.security_events (user_id, event) values (v_user, 'mfa_revoked');
  perform private.end_sessions(v_user, (auth.jwt() ->> 'session_id')::uuid);
end;
$$;

-- ---------------------------------------------------------------------------------------------------------------
-- Part C: delete my account (proposal §10.6 / §11.4; R2–R4). Identity only from auth.uid(); fresh proof required
-- inside the function; household row locked before membership is read. Sole owner: the household and all its
-- data (including pending invitations) go with the account. Owner with other people: refused (R3). Permanent (R4).
-- ---------------------------------------------------------------------------------------------------------------
create or replace function public.delete_my_account(p_confirm text)
returns text
language plpgsql
volatile
security definer
set search_path = ''
as $$
declare
  v_user uuid := auth.uid();
  v_household uuid;
  v_role text;
  v_others integer;
begin
  if p_confirm is distinct from 'DELETE' then
    raise exception 'delete: type DELETE to confirm' using errcode = '22023';
  end if;
  perform private.recent_reauth('delete_account');

  select m.household_id into v_household from public.household_members m where m.user_id = v_user;
  if v_household is not null then
    perform 1 from public.households h where h.id = v_household for update;
    select m.role::text into v_role from public.household_members m
    where m.user_id = v_user and m.household_id = v_household;
    if v_role is null then
      raise exception 'permission denied: your household changed; please try again' using errcode = '42501';
    end if;
    if v_role = 'owner' then
      select count(*) into v_others from public.household_members m
      where m.household_id = v_household and m.user_id <> v_user;
      if v_others > 0 then
        raise exception 'permission denied: remove the other people from your household first' using errcode = '42501';
      end if;
      delete from public.households h where h.id = v_household;
    end if;
  end if;
  -- households.created_by does not cascade: any household still naming this person blocks deletion (fail closed).
  if exists (select 1 from public.households h where h.created_by = v_user) then
    raise exception 'permission denied: this account still owns a household' using errcode = '42501';
  end if;
  insert into private.security_events (user_id, event) values (v_user, 'account_deleted');
  delete from auth.users u where u.id = v_user;
  return 'deleted';
end;
$$;

-- ---------------------------------------------------------------------------------------------------------------
-- Owner-assisted 2FA reset (proposal §10.7, R11). Run only by Ryan in the SQL editor after confirming identity in
-- person or by a call he places to a number he already had. NOT executable by anon/authenticated.
-- ---------------------------------------------------------------------------------------------------------------
create or replace function private.owner_reset_mfa(p_user uuid, p_reason text)
returns void
language plpgsql
volatile
security definer
set search_path = ''
as $$
begin
  if p_user is null or p_reason is null or length(trim(p_reason)) < 5 or length(p_reason) > 200 then
    raise exception 'owner reset: a user id and a short reason are required' using errcode = '22023';
  end if;
  if not exists (select 1 from auth.users u where u.id = p_user) then
    raise exception 'owner reset: no such account' using errcode = '22023';
  end if;
  delete from private.mfa_approved_factors a where a.user_id = p_user;
  delete from auth.mfa_factors f where f.user_id = p_user;
  perform private.end_sessions(p_user, null);
  insert into private.security_events (user_id, event, detail) values (p_user, 'owner_mfa_reset', p_reason);
end;
$$;

revoke all on function private.owner_reset_mfa(uuid, text) from public, anon, authenticated;

revoke all on function public.my_security_status(), public.finish_password_change(),
  public.approve_my_mfa_factor(uuid), public.turn_off_my_two_factor(), public.delete_my_account(text)
  from public, anon, authenticated;
grant execute on function public.my_security_status(), public.finish_password_change(),
  public.approve_my_mfa_factor(uuid), public.turn_off_my_two_factor(), public.delete_my_account(text)
  to authenticated;

-- New functions in public are not callable by PUBLIC/anon/authenticated until a migration grants it explicitly
-- (Supabase's default grants EXECUTE to anon and authenticated). Checked by scripts/rls-local/coverage.sql.
alter default privileges for role postgres in schema public revoke execute on functions from public, anon, authenticated;

commit;
